FILES[PROJECT_ROOT / 'backend/alembic/env.py'] = 'from logging.config import fileConfig\n\nfrom alembic import context\n\nfrom app.core.config import settings\nfrom app.core.database import engine\nfrom app.models.base import Base\nfrom app.models.email_verification_token import EmailVerificationToken\nfrom app.models.password_reset_token import PasswordResetToken\nfrom app.models.user import User\nfrom app.models.user_credential import UserCredential\nfrom app.models.user_session import UserSession\n\n\nconfig = context.config\n\nif config.config_file_name is not None:\n    fileConfig(config.config_file_name)\n\n_ = (\n    EmailVerificationToken,\n    PasswordResetToken,\n    User,\n    UserCredential,\n    UserSession,\n)\ntarget_metadata = Base.metadata\n\n\ndef run_migrations_offline() -> None:\n    context.configure(\n        url=settings.database_url,\n        target_metadata=target_metadata,\n        literal_binds=True,\n        dialect_opts={"paramstyle": "named"},\n        compare_type=True,\n    )\n\n    with context.begin_transaction():\n        context.run_migrations()\n\n\ndef run_migrations_online() -> None:\n    with engine.connect() as connection:\n        context.configure(\n            connection=connection,\n            target_metadata=target_metadata,\n            compare_type=True,\n        )\n\n        with context.begin_transaction():\n            context.run_migrations()\n\n\nif context.is_offline_mode():\n    run_migrations_offline()\nelse:\n    run_migrations_online()\n'
FILES[PROJECT_ROOT / 'backend/app/security/password_reset_tokens.py'] = 'import hashlib\nimport secrets\n\n\ndef create_password_reset_token() -> str:\n    return secrets.token_urlsafe(32)\n\n\ndef hash_password_reset_token(token: str) -> str:\n    return hashlib.sha256(token.encode("utf-8")).hexdigest()\n'
FILES[PROJECT_ROOT / 'backend/app/security/__init__.py'] = 'from .email_verification_tokens import (\n    create_email_verification_token,\n    hash_email_verification_token,\n)\nfrom .password_reset_tokens import (\n    create_password_reset_token,\n    hash_password_reset_token,\n)\nfrom .passwords import hash_password, verify_password\nfrom .tokens import (\n    create_access_token,\n    create_refresh_token,\n    decode_access_token,\n    hash_refresh_token,\n)\n\n\n__all__ = [\n    "create_access_token",\n    "create_email_verification_token",\n    "create_refresh_token",\n    "decode_access_token",\n    "hash_email_verification_token",\n    "create_password_reset_token",\n    "hash_password",\n    "hash_password_reset_token",\n    "hash_refresh_token",\n    "verify_password",\n]\n'
FILES[PROJECT_ROOT / 'backend/app/repositories/password_reset_repository.py'] = 'import uuid\nfrom datetime import datetime\n\nfrom sqlalchemy import select, update\nfrom sqlalchemy.orm import Session\n\nfrom ..models.password_reset_token import PasswordResetToken\n\n\nclass PasswordResetRepository:\n    def __init__(self, db: Session) -> None:\n        self.db = db\n\n    def get_by_hash(self, token_hash: str) -> PasswordResetToken | None:\n        statement = select(PasswordResetToken).where(\n            PasswordResetToken.token_hash == token_hash\n        )\n        return self.db.scalars(statement).first()\n\n    def create(\n        self,\n        *,\n        user_id: uuid.UUID,\n        token_hash: str,\n        expires_at: datetime,\n    ) -> PasswordResetToken:\n        record = PasswordResetToken(\n            user_id=user_id,\n            token_hash=token_hash,\n            expires_at=expires_at,\n        )\n        self.db.add(record)\n        self.db.flush()\n        return record\n\n    def invalidate_active_for_user(\n        self,\n        user_id: uuid.UUID,\n        when: datetime,\n    ) -> None:\n        statement = (\n            update(PasswordResetToken)\n            .where(\n                PasswordResetToken.user_id == user_id,\n                PasswordResetToken.used_at.is_(None),\n                PasswordResetToken.invalidated_at.is_(None),\n            )\n            .values(invalidated_at=when)\n        )\n        self.db.execute(statement)\n'
FILES[PROJECT_ROOT / 'backend/app/repositories/__init__.py'] = 'from .email_verification_repository import EmailVerificationRepository\nfrom .password_reset_repository import PasswordResetRepository\nfrom .user_credential_repository import UserCredentialRepository\nfrom .user_repository import UserRepository\nfrom .user_session_repository import UserSessionRepository\n\n\n__all__ = [\n    "EmailVerificationRepository",\n    "PasswordResetRepository",\n    "UserCredentialRepository",\n    "UserRepository",\n    "UserSessionRepository",\n]\n'
FILES[PROJECT_ROOT / 'backend/app/repositories/user_credential_repository.py'] = 'import uuid\nfrom datetime import datetime\n\nfrom sqlalchemy.orm import Session\n\nfrom ..models.user_credential import UserCredential\n\n\nclass UserCredentialRepository:\n    def __init__(self, db: Session) -> None:\n        self.db = db\n\n    def get_by_user_id(self, user_id: uuid.UUID) -> UserCredential | None:\n        return self.db.get(UserCredential, user_id)\n\n    def create(\n        self,\n        user_id: uuid.UUID,\n        password_hash: str,\n    ) -> UserCredential:\n        credential = UserCredential(\n            user_id=user_id,\n            password_hash=password_hash,\n        )\n        self.db.add(credential)\n        self.db.flush()\n        return credential\n\n\n    def update_password(\n        self,\n        *,\n        user_id: uuid.UUID,\n        password_hash: str,\n        changed_at: datetime,\n    ) -> UserCredential | None:\n        credential = self.get_by_user_id(user_id)\n        if credential is None:\n            return None\n\n        credential.password_hash = password_hash\n        credential.password_changed_at = changed_at\n        return credential\n'
FILES[PROJECT_ROOT / 'backend/app/repositories/user_session_repository.py'] = 'import uuid\nfrom datetime import datetime\n\nfrom sqlalchemy import select, update\nfrom sqlalchemy.orm import Session\n\nfrom ..models.user_session import UserSession\n\n\nclass UserSessionRepository:\n    def __init__(self, db: Session) -> None:\n        self.db = db\n\n    def get_by_id(self, session_id: uuid.UUID) -> UserSession | None:\n        return self.db.get(UserSession, session_id)\n\n    def get_by_refresh_hash(self, refresh_token_hash: str) -> UserSession | None:\n        statement = select(UserSession).where(\n            UserSession.refresh_token_hash == refresh_token_hash\n        )\n        return self.db.scalars(statement).first()\n\n    def create(\n        self,\n        user_id: uuid.UUID,\n        refresh_token_hash: str,\n        expires_at: datetime,\n    ) -> UserSession:\n        session = UserSession(\n            user_id=user_id,\n            refresh_token_hash=refresh_token_hash,\n            expires_at=expires_at,\n        )\n        self.db.add(session)\n        self.db.flush()\n        return session\n\n\n    def revoke_all_for_user(\n        self,\n        user_id: uuid.UUID,\n        when: datetime,\n    ) -> None:\n        statement = (\n            update(UserSession)\n            .where(\n                UserSession.user_id == user_id,\n                UserSession.revoked_at.is_(None),\n            )\n            .values(revoked_at=when)\n        )\n        self.db.execute(statement)\n'
FILES[PROJECT_ROOT / 'backend/app/services/password_reset_service.py'] = 'from datetime import datetime, timedelta, timezone\n\nfrom sqlalchemy.orm import Session\n\nfrom ..core.config import settings\nfrom ..models.user import User\nfrom ..repositories.password_reset_repository import PasswordResetRepository\nfrom ..repositories.user_credential_repository import UserCredentialRepository\nfrom ..repositories.user_repository import UserRepository\nfrom ..repositories.user_session_repository import UserSessionRepository\nfrom ..security.password_reset_tokens import (\n    create_password_reset_token,\n    hash_password_reset_token,\n)\nfrom ..security.passwords import hash_password\nfrom .user_service import UserService\n\n\nclass InvalidPasswordResetTokenError(Exception):\n    pass\n\n\nclass PasswordResetService:\n    def __init__(self, db: Session) -> None:\n        self.db = db\n        self.tokens = PasswordResetRepository(db)\n        self.users = UserRepository(db)\n        self.credentials = UserCredentialRepository(db)\n        self.sessions = UserSessionRepository(db)\n\n    def request_reset(self, email: str) -> tuple[User, str] | None:\n        normalized_email = UserService.normalize_email(email)\n        user = self.users.get_by_email(normalized_email)\n\n        # Public callers receive the same response for missing, inactive,\n        # and valid accounts. Returning None here is an internal detail.\n        if user is None or not user.is_active:\n            return None\n\n        now = datetime.now(timezone.utc)\n        self.tokens.invalidate_active_for_user(user.id, now)\n\n        raw_token = create_password_reset_token()\n        self.tokens.create(\n            user_id=user.id,\n            token_hash=hash_password_reset_token(raw_token),\n            expires_at=now + timedelta(\n                minutes=settings.password_reset_expire_minutes,\n            ),\n        )\n        self.db.commit()\n        return user, raw_token\n\n    def reset_password(\n        self,\n        *,\n        raw_token: str,\n        new_password: str,\n    ) -> User:\n        now = datetime.now(timezone.utc)\n        token = self.tokens.get_by_hash(\n            hash_password_reset_token(raw_token)\n        )\n\n        if (\n            token is None\n            or token.used_at is not None\n            or token.invalidated_at is not None\n            or token.expires_at <= now\n        ):\n            raise InvalidPasswordResetTokenError\n\n        user = self.users.get_by_id(token.user_id)\n        if user is None or not user.is_active:\n            raise InvalidPasswordResetTokenError\n\n        credential = self.credentials.update_password(\n            user_id=user.id,\n            password_hash=hash_password(new_password),\n            changed_at=now,\n        )\n        if credential is None:\n            raise InvalidPasswordResetTokenError\n\n        token.used_at = now\n\n        # SessionLocal uses autoflush=False. Persist the successful-use\n        # marker before invalidating any remaining active reset tokens.\n        self.db.flush()\n\n        self.tokens.invalidate_active_for_user(user.id, now)\n        self.sessions.revoke_all_for_user(user.id, now)\n        self.db.commit()\n        self.db.refresh(user)\n        return user\n'
FILES[PROJECT_ROOT / 'backend/app/services/__init__.py'] = 'from .auth_service import (\n    AuthenticationService,\n    InactiveUserError,\n    InvalidCredentialsError,\n    InvalidRefreshTokenError,\n)\nfrom .email_delivery_service import EmailDeliveryService\nfrom .email_verification_service import (\n    EmailVerificationService,\n    InvalidEmailVerificationTokenError,\n)\nfrom .password_reset_service import (\n    InvalidPasswordResetTokenError,\n    PasswordResetService,\n)\nfrom .user_service import UserAlreadyExistsError, UserNotFoundError, UserService\n\n\n__all__ = [\n    "AuthenticationService",\n    "EmailDeliveryService",\n    "EmailVerificationService",\n    "InactiveUserError",\n    "InvalidCredentialsError",\n    "InvalidEmailVerificationTokenError",\n    "InvalidRefreshTokenError",\n    "InvalidPasswordResetTokenError",\n    "PasswordResetService",\n    "UserAlreadyExistsError",\n    "UserNotFoundError",\n    "UserService",\n]\n'
FILES[PROJECT_ROOT / 'backend/app/schemas/auth.py'] = 'from pydantic import BaseModel, EmailStr, Field\n\n\nclass RegistrationRequest(BaseModel):\n    email: EmailStr\n    password: str = Field(\n        min_length=15,\n        max_length=128,\n    )\n\n\nclass LoginRequest(BaseModel):\n    email: EmailStr\n    password: str = Field(\n        min_length=1,\n        max_length=128,\n    )\n\n\nclass RefreshRequest(BaseModel):\n    refresh_token: str = Field(\n        min_length=32,\n        max_length=512,\n    )\n\n\nclass LogoutRequest(BaseModel):\n    refresh_token: str = Field(\n        min_length=32,\n        max_length=512,\n    )\n\n\nclass TokenResponse(BaseModel):\n    access_token: str\n    refresh_token: str\n    token_type: str = "bearer"\n    expires_in: int\n\n\nclass VerifyEmailRequest(BaseModel):\n    token: str = Field(\n        min_length=32,\n        max_length=512,\n    )\n\n\nclass VerificationStatusResponse(BaseModel):\n    status: str\n\n\n\nclass ForgotPasswordRequest(BaseModel):\n    email: EmailStr\n\n\nclass PasswordResetStatusResponse(BaseModel):\n    status: str\n'
FILES[PROJECT_ROOT / 'backend/app/schemas/__init__.py'] = 'from .auth import (\n    ForgotPasswordRequest,\n    LoginRequest,\n    LogoutRequest,\n    PasswordResetStatusResponse,\n    RefreshRequest,\n    RegistrationRequest,\n    TokenResponse,\n    VerificationStatusResponse,\n    VerifyEmailRequest,\n)\nfrom .user import UserCreate, UserResponse\n\n\n__all__ = [\n    "ForgotPasswordRequest",\n    "LoginRequest",\n    "LogoutRequest",\n    "PasswordResetStatusResponse",\n    "RefreshRequest",\n    "RegistrationRequest",\n    "TokenResponse",\n    "VerificationStatusResponse",\n    "VerifyEmailRequest",\n    "UserCreate",\n    "UserResponse",\n]\n'
FILES[PROJECT_ROOT / 'backend/app/services/email_delivery_service.py'] = 'from html import escape\nfrom urllib.parse import urlencode\n\nfrom ..core.config import settings\nfrom ..providers.resend_email_provider import ResendEmailProvider\n\n\nclass EmailDeliveryService:\n    def __init__(\n        self,\n        provider: ResendEmailProvider | None = None,\n    ) -> None:\n        self.provider = provider or ResendEmailProvider()\n\n    @staticmethod\n    def build_verification_url(raw_token: str) -> str:\n        query = urlencode({"token": raw_token})\n        separator = (\n            "&"\n            if "?" in settings.email_verification_url\n            else "?"\n        )\n        return (\n            f"{settings.email_verification_url}"\n            f"{separator}{query}"\n        )\n\n    @staticmethod\n    def build_password_reset_url(raw_token: str) -> str:\n        query = urlencode({"token": raw_token})\n        separator = "&" if "?" in settings.password_reset_url else "?"\n        return f"{settings.password_reset_url}{separator}{query}"\n\n    def send_verification_email(\n        self,\n        *,\n        to_email: str,\n        raw_token: str,\n    ) -> None:\n        verification_url = self.build_verification_url(raw_token)\n        safe_url = escape(verification_url, quote=True)\n\n        subject = "Verify your Philotes email"\n\n        html = f"""<!doctype html>\n<html>\n  <body>\n    <h2>Verify your Philotes email</h2>\n    <p>\n      Confirm that this email address belongs to you before\n      using Philotes community features.\n    </p>\n    <p>\n      <a href="{safe_url}">Verify my email</a>\n    </p>\n    <p>\n      This verification link expires in\n      {settings.email_verification_expire_hours} hours.\n    </p>\n    <p>\n      If you did not create a Philotes account, you can ignore\n      this message.\n    </p>\n  </body>\n</html>\n"""\n\n        text = (\n            "Verify your Philotes email\\n\\n"\n            "Confirm your email address using this link:\\n"\n            f"{verification_url}\\n\\n"\n            "This verification link expires in "\n            f"{settings.email_verification_expire_hours} hours.\\n\\n"\n            "If you did not create a Philotes account, "\n            "you can ignore this message."\n        )\n\n        self.provider.send(\n            to_email=to_email,\n            subject=subject,\n            html=html,\n            text=text,\n        )\n\n\n    def send_password_reset_email(\n        self,\n        *,\n        to_email: str,\n        raw_token: str,\n    ) -> None:\n        reset_url = self.build_password_reset_url(raw_token)\n        safe_url = escape(reset_url, quote=True)\n\n        subject = "Reset your Philotes password"\n\n        html = f"""<!doctype html>\n<html>\n  <body>\n    <h2>Reset your Philotes password</h2>\n    <p>\n      We received a request to reset the password for your\n      Philotes account.\n    </p>\n    <p>\n      <a href="{safe_url}">Reset my password</a>\n    </p>\n    <p>\n      This link expires in\n      {settings.password_reset_expire_minutes} minutes.\n    </p>\n    <p>\n      If you did not request a password reset, you can ignore\n      this message and your password will remain unchanged.\n    </p>\n  </body>\n</html>\n"""\n\n        text = (\n            "Reset your Philotes password\\n\\n"\n            "Use this link to choose a new password:\\n"\n            f"{reset_url}\\n\\n"\n            "This link expires in "\n            f"{settings.password_reset_expire_minutes} minutes.\\n\\n"\n            "If you did not request a password reset, "\n            "you can ignore this message."\n        )\n\n        self.provider.send(\n            to_email=to_email,\n            subject=subject,\n            html=html,\n            text=text,\n        )\n'
FILES[PROJECT_ROOT / 'backend/app/presentation/security_pages.py'] = 'from html import escape\n\n\ndef philotes_security_page(\n    *,\n    title: str,\n    message: str,\n    body_html: str = "",\n    tone: str = "standard",\n) -> str:\n    safe_title = escape(title)\n    safe_message = escape(message)\n\n    status_icon = "✓" if tone == "success" else "✦"\n\n    return f"""<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta\n    name="viewport"\n    content="width=device-width, initial-scale=1"\n  >\n  <title>{safe_title} | Philotes</title>\n  <style>\n    :root {{\n      --philotes-navy: #0b2545;\n      --philotes-gold: #c89b3c;\n      --philotes-ivory: #f7f2e8;\n      --philotes-white: #ffffff;\n      --philotes-silver: #7a8796;\n      --philotes-line: #d6c7a3;\n      --philotes-success: #2f6f57;\n    }}\n\n    * {{\n      box-sizing: border-box;\n    }}\n\n    html,\n    body {{\n      margin: 0;\n      min-height: 100%;\n      background: var(--philotes-ivory);\n      color: var(--philotes-navy);\n      font-family:\n        Inter,\n        ui-sans-serif,\n        system-ui,\n        -apple-system,\n        BlinkMacSystemFont,\n        "Segoe UI",\n        sans-serif;\n    }}\n\n    body {{\n      min-height: 100vh;\n      display: grid;\n      place-items: center;\n      padding: 24px;\n    }}\n\n    .page-shell {{\n      width: min(100%, 720px);\n    }}\n\n    .brand {{\n      text-align: center;\n      margin-bottom: 20px;\n    }}\n\n    .brand-mark {{\n      width: 64px;\n      height: 64px;\n      margin: 0 auto 12px;\n      border: 2px solid var(--philotes-gold);\n      border-radius: 50%;\n      display: grid;\n      place-items: center;\n      background: var(--philotes-white);\n      color: var(--philotes-navy);\n      font-size: 28px;\n      font-weight: 800;\n      box-shadow: 0 8px 24px rgba(11, 37, 69, 0.08);\n    }}\n\n    .brand-name {{\n      margin: 0;\n      font-size: clamp(28px, 5vw, 40px);\n      letter-spacing: 0.04em;\n      font-weight: 800;\n    }}\n\n    .tagline {{\n      margin: 6px 0 0;\n      color: var(--philotes-silver);\n      font-size: 15px;\n    }}\n\n    .card {{\n      background: var(--philotes-white);\n      border: 1.5px solid var(--philotes-gold);\n      border-radius: 24px;\n      padding: clamp(24px, 5vw, 42px);\n      box-shadow: 0 18px 50px rgba(11, 37, 69, 0.10);\n    }}\n\n    .status-icon {{\n      width: 52px;\n      height: 52px;\n      border-radius: 50%;\n      margin-bottom: 20px;\n      display: grid;\n      place-items: center;\n      background: #f3ead6;\n      color: var(--philotes-navy);\n      font-size: 26px;\n      font-weight: 800;\n    }}\n\n    .status-icon.success {{\n      background: #e6f3ec;\n      color: var(--philotes-success);\n    }}\n\n    h1 {{\n      margin: 0 0 12px;\n      font-size: clamp(28px, 5vw, 38px);\n      line-height: 1.15;\n    }}\n\n    .message {{\n      margin: 0 0 26px;\n      color: #425466;\n      font-size: 17px;\n      line-height: 1.65;\n    }}\n\n    .primary-action {{\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      width: 100%;\n      min-height: 52px;\n      border: 0;\n      border-radius: 14px;\n      background: var(--philotes-navy);\n      color: var(--philotes-white);\n      font: inherit;\n      font-weight: 700;\n      font-size: 16px;\n      cursor: pointer;\n      text-decoration: none;\n      transition:\n        transform 120ms ease,\n        box-shadow 120ms ease;\n    }}\n\n    .primary-action:hover {{\n      transform: translateY(-1px);\n      box-shadow: 0 8px 18px rgba(11, 37, 69, 0.18);\n    }}\n\n    .primary-action:focus-visible {{\n      outline: 3px solid rgba(200, 155, 60, 0.45);\n      outline-offset: 3px;\n    }}\n\n    .help-text {{\n      margin: 22px 0 0;\n      color: var(--philotes-silver);\n      font-size: 14px;\n      line-height: 1.55;\n      text-align: center;\n    }}\n\n    .footer {{\n      margin-top: 18px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 0;\n      color: var(--philotes-navy);\n      font-size: 12px;\n      font-weight: 600;\n      letter-spacing: 3px;\n      line-height: 1;\n      white-space: nowrap;\n    }}\n\n    .footer-prefix {{\n      margin-right: 6px;\n    }}\n\n    .titan-logo {{\n      width: 22px;\n      height: 22px;\n      object-fit: contain;\n      flex: 0 0 22px;\n    }}\n\n    .footer-titan {{\n      margin-left: 4px;\n    }}\n\n    @media (max-width: 430px) {{\n      .footer {{\n        font-size: 10px;\n        letter-spacing: 2px;\n      }}\n\n      .titan-logo {{\n        width: 20px;\n        height: 20px;\n        flex-basis: 20px;\n      }}\n    }}\n\n    @media (max-width: 520px) {{\n      body {{\n        padding: 16px;\n      }}\n\n      .card {{\n        border-radius: 18px;\n      }}\n    }}\n  </style>\n</head>\n<body>\n  <main class="page-shell">\n    <header class="brand" aria-label="Philotes">\n      <div class="brand-mark" aria-hidden="true">Φ</div>\n      <h2 class="brand-name">PHILOTES</h2>\n      <p class="tagline">A Community for Friendship</p>\n    </header>\n\n    <section class="card">\n      <div class="status-icon {"success" if tone == "success" else ""}">\n        {status_icon}\n      </div>\n      <h1>{safe_title}</h1>\n      <p class="message">{safe_message}</p>\n      {body_html}\n    </section>\n\n    <footer class="footer" aria-label="Brought to you by Titan">\n      <span class="footer-prefix">BROUGHT TO YOU BY</span>\n      <img\n        class="titan-logo"\n        src="/api/v1/auth/security-assets/titan-logo.png"\n        alt=""\n        aria-hidden="true"\n      >\n      <span class="footer-titan">TITAN</span>\n    </footer>\n  </main>\n</body>\n</html>\n"""\n\n\ndef verification_confirmation_page(*, token: str) -> str:\n    safe_token = escape(token, quote=True)\n\n    body = f"""\n<form method="post" action="/api/v1/auth/verify-email-link">\n  <input type="hidden" name="token" value="{safe_token}">\n  <button class="primary-action" type="submit">\n    Verify Email Address\n  </button>\n</form>\n<p class="help-text">\n  This confirmation protects your account from automated link scanners.\n  If you did not create a Philotes account, you can close this window.\n</p>\n"""\n\n    return philotes_security_page(\n        title="Verify your email",\n        message=(\n            "Confirm your email address to finish securing your "\n            "Philotes account."\n        ),\n        body_html=body,\n    )\n\n\ndef verification_success_page() -> str:\n    body = """\n<p class="help-text">\n  You may close this window and return to Philotes.\n</p>\n"""\n\n    return philotes_security_page(\n        title="Email verified",\n        message=(\n            "Your Philotes email address has been successfully verified."\n        ),\n        body_html=body,\n        tone="success",\n    )\n\n\ndef verification_error_page() -> str:\n    body = """\n<p class="help-text">\n  Request a new verification email from Philotes and try again.\n</p>\n"""\n\n    return philotes_security_page(\n        title="Verification link unavailable",\n        message=(\n            "This verification link is invalid, expired, or has "\n            "already been used."\n        ),\n        body_html=body,\n    )\n\n\n\ndef password_reset_form_page(\n    *,\n    token: str,\n    error_message: str | None = None,\n) -> str:\n    safe_token = escape(token, quote=True)\n    error_html = (\n        f\'<p class="form-error" role="alert">{escape(error_message)}</p>\'\n        if error_message\n        else ""\n    )\n\n    body = f"""\n{error_html}\n<form method="post" action="/api/v1/auth/reset-password-link">\n  <input type="hidden" name="token" value="{safe_token}">\n\n  <div style="margin-bottom: 16px;">\n    <label\n      for="new-password"\n      style="display:block;margin-bottom:8px;font-weight:700;"\n    >\n      New password\n    </label>\n    <input\n      id="new-password"\n      name="new_password"\n      type="password"\n      minlength="15"\n      maxlength="128"\n      autocomplete="new-password"\n      required\n      style="\n        width:100%;\n        min-height:50px;\n        border:1px solid #aeb8c2;\n        border-radius:12px;\n        padding:12px 14px;\n        font:inherit;\n      "\n    >\n  </div>\n\n  <div style="margin-bottom: 22px;">\n    <label\n      for="confirm-password"\n      style="display:block;margin-bottom:8px;font-weight:700;"\n    >\n      Confirm new password\n    </label>\n    <input\n      id="confirm-password"\n      name="confirm_password"\n      type="password"\n      minlength="15"\n      maxlength="128"\n      autocomplete="new-password"\n      required\n      style="\n        width:100%;\n        min-height:50px;\n        border:1px solid #aeb8c2;\n        border-radius:12px;\n        padding:12px 14px;\n        font:inherit;\n      "\n    >\n  </div>\n\n  <button class="primary-action" type="submit">\n    Change Password\n  </button>\n</form>\n<p class="help-text">\n  Use at least 15 characters. After your password changes,\n  Philotes will sign out all existing sessions for your security.\n</p>\n"""\n\n    return philotes_security_page(\n        title="Reset your password",\n        message=(\n            "Choose a new password for your Philotes account."\n        ),\n        body_html=body,\n    )\n\n\ndef password_reset_success_page() -> str:\n    body = """\n<p class="help-text">\n  All existing Philotes sessions have been signed out.\n  You may close this window and sign in again with your new password.\n</p>\n"""\n\n    return philotes_security_page(\n        title="Password changed",\n        message=(\n            "Your Philotes password has been updated successfully."\n        ),\n        body_html=body,\n        tone="success",\n    )\n\n\ndef password_reset_error_page() -> str:\n    body = """\n<p class="help-text">\n  Request a new password-reset email from Philotes and try again.\n</p>\n"""\n\n    return philotes_security_page(\n        title="Reset link unavailable",\n        message=(\n            "This password-reset link is invalid, expired, or has "\n            "already been used."\n        ),\n        body_html=body,\n    )\n'
FILES[PROJECT_ROOT / 'backend/app/presentation/__init__.py'] = 'from .security_pages import (\n    password_reset_error_page,\n    password_reset_form_page,\n    password_reset_success_page,\n    verification_confirmation_page,\n    verification_error_page,\n    verification_success_page,\n)\n\n__all__ = [\n    "password_reset_error_page",\n    "password_reset_form_page",\n    "password_reset_success_page",\n    "verification_confirmation_page",\n    "verification_error_page",\n    "verification_success_page",\n]\n'
FILES[PROJECT_ROOT / 'backend/app/api/routes/auth.py'] = 'from fastapi import (\n    APIRouter,\n    BackgroundTasks,\n    Depends,\n    Form,\n    HTTPException,\n    Query,\n    Response,\n    status,\n)\nfrom fastapi.responses import FileResponse, HTMLResponse\nfrom sqlalchemy.exc import SQLAlchemyError\nfrom sqlalchemy.orm import Session\n\nfrom ...core.config import BACKEND_ROOT, settings\nfrom ...core.database import get_db\nfrom ...schemas.auth import (\n    ForgotPasswordRequest,\n    LoginRequest,\n    LogoutRequest,\n    PasswordResetStatusResponse,\n    RefreshRequest,\n    RegistrationRequest,\n    TokenResponse,\n    VerificationStatusResponse,\n    VerifyEmailRequest,\n)\nfrom ...schemas.user import UserResponse\nfrom ...security.authentication import get_current_user\nfrom ...services.email_delivery_service import EmailDeliveryService\nfrom ...services.email_verification_service import (\n    EmailVerificationService,\n    InvalidEmailVerificationTokenError,\n)\nfrom ...services.auth_service import (\n    AuthenticationService,\n    InactiveUserError,\n    InvalidCredentialsError,\n    InvalidRefreshTokenError,\n)\nfrom ...services.password_reset_service import (\n    InvalidPasswordResetTokenError,\n    PasswordResetService,\n)\nfrom ...services.user_service import UserAlreadyExistsError\nfrom ...models.user import User\nfrom ...presentation.security_pages import (\n    password_reset_error_page,\n    password_reset_form_page,\n    password_reset_success_page,\n    verification_confirmation_page,\n    verification_error_page,\n    verification_success_page,\n)\n\n\nrouter = APIRouter(\n    prefix="/auth",\n    tags=["Authentication"],\n)\n\n\n@router.post(\n    "/register",\n    response_model=UserResponse,\n    status_code=status.HTTP_201_CREATED,\n)\ndef register(\n    payload: RegistrationRequest,\n    background_tasks: BackgroundTasks,\n    db: Session = Depends(get_db),\n) -> UserResponse:\n    service = AuthenticationService(db)\n\n    try:\n        user, verification_token = service.register(\n            email=str(payload.email),\n            password=payload.password,\n        )\n\n        if settings.email_delivery_enabled:\n            background_tasks.add_task(\n                EmailDeliveryService().send_verification_email,\n                to_email=user.email,\n                raw_token=verification_token,\n            )\n\n        return user\n    except UserAlreadyExistsError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_409_CONFLICT,\n            detail="An account with that email already exists.",\n        ) from exc\n    except SQLAlchemyError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\n            detail="Database unavailable",\n        ) from exc\n\n\n@router.post(\n    "/login",\n    response_model=TokenResponse,\n)\ndef login(\n    payload: LoginRequest,\n    db: Session = Depends(get_db),\n) -> TokenResponse:\n    service = AuthenticationService(db)\n\n    try:\n        _, access_token, refresh_token, expires_in = service.login(\n            email=str(payload.email),\n            password=payload.password,\n        )\n        return TokenResponse(\n            access_token=access_token,\n            refresh_token=refresh_token,\n            expires_in=expires_in,\n        )\n    except InvalidCredentialsError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_401_UNAUTHORIZED,\n            detail="Invalid email or password.",\n        ) from exc\n    except InactiveUserError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_403_FORBIDDEN,\n            detail="Account is inactive.",\n        ) from exc\n    except SQLAlchemyError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\n            detail="Database unavailable",\n        ) from exc\n\n\n@router.post(\n    "/refresh",\n    response_model=TokenResponse,\n)\ndef refresh(\n    payload: RefreshRequest,\n    db: Session = Depends(get_db),\n) -> TokenResponse:\n    try:\n        access_token, refresh_token, expires_in = AuthenticationService(\n            db\n        ).refresh(payload.refresh_token)\n        return TokenResponse(\n            access_token=access_token,\n            refresh_token=refresh_token,\n            expires_in=expires_in,\n        )\n    except InvalidRefreshTokenError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_401_UNAUTHORIZED,\n            detail="Invalid or expired refresh token.",\n        ) from exc\n\n\n@router.post(\n    "/logout",\n    status_code=status.HTTP_204_NO_CONTENT,\n)\ndef logout(\n    payload: LogoutRequest,\n    db: Session = Depends(get_db),\n) -> Response:\n    AuthenticationService(db).logout(payload.refresh_token)\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n\n\n@router.get(\n    "/me",\n    response_model=UserResponse,\n)\ndef me(\n    current_user: User = Depends(get_current_user),\n) -> UserResponse:\n    return current_user\n\n\n@router.post(\n    "/verify-email",\n    response_model=VerificationStatusResponse,\n)\ndef verify_email(\n    payload: VerifyEmailRequest,\n    db: Session = Depends(get_db),\n) -> VerificationStatusResponse:\n    try:\n        EmailVerificationService(db).verify(payload.token)\n        return VerificationStatusResponse(status="verified")\n    except InvalidEmailVerificationTokenError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            detail="Invalid or expired verification token.",\n        ) from exc\n\n\n@router.post(\n    "/resend-verification",\n    response_model=VerificationStatusResponse,\n    status_code=status.HTTP_202_ACCEPTED,\n)\ndef resend_verification(\n    background_tasks: BackgroundTasks,\n    current_user: User = Depends(get_current_user),\n    db: Session = Depends(get_db),\n) -> VerificationStatusResponse:\n    if current_user.email_verified:\n        return VerificationStatusResponse(status="already_verified")\n\n    verification_token = EmailVerificationService(db).issue_token(\n        current_user.id\n    )\n\n    if settings.email_delivery_enabled:\n        background_tasks.add_task(\n            EmailDeliveryService().send_verification_email,\n            to_email=current_user.email,\n            raw_token=verification_token,\n        )\n\n    return VerificationStatusResponse(status="verification_pending")\n\n\n@router.post(\n    "/forgot-password",\n    response_model=PasswordResetStatusResponse,\n    status_code=status.HTTP_202_ACCEPTED,\n)\ndef forgot_password(\n    payload: ForgotPasswordRequest,\n    background_tasks: BackgroundTasks,\n    db: Session = Depends(get_db),\n) -> PasswordResetStatusResponse:\n    reset = PasswordResetService(db).request_reset(str(payload.email))\n\n    if reset is not None and settings.email_delivery_enabled:\n        user, raw_token = reset\n        background_tasks.add_task(\n            EmailDeliveryService().send_password_reset_email,\n            to_email=user.email,\n            raw_token=raw_token,\n        )\n\n    # Deliberately identical whether or not the account exists.\n    return PasswordResetStatusResponse(status="password_reset_pending")\n\n\n@router.get(\n    "/reset-password-link",\n    response_class=HTMLResponse,\n    include_in_schema=False,\n)\ndef password_reset_landing_page(\n    token: str = Query(min_length=32, max_length=512),\n) -> HTMLResponse:\n    return HTMLResponse(\n        content=password_reset_form_page(token=token)\n    )\n\n\n@router.post(\n    "/reset-password-link",\n    response_class=HTMLResponse,\n    include_in_schema=False,\n)\ndef password_reset_landing_confirm(\n    token: str = Form(..., min_length=32, max_length=512),\n    new_password: str = Form(..., min_length=15, max_length=128),\n    confirm_password: str = Form(..., min_length=15, max_length=128),\n    db: Session = Depends(get_db),\n) -> HTMLResponse:\n    if new_password != confirm_password:\n        return HTMLResponse(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            content=password_reset_form_page(\n                token=token,\n                error_message="The password entries do not match.",\n            ),\n        )\n\n    try:\n        PasswordResetService(db).reset_password(\n            raw_token=token,\n            new_password=new_password,\n        )\n        return HTMLResponse(\n            content=password_reset_success_page()\n        )\n    except InvalidPasswordResetTokenError:\n        return HTMLResponse(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            content=password_reset_error_page(),\n        )\n\n\n@router.get(\n    "/security-assets/titan-logo.png",\n    response_class=FileResponse,\n    include_in_schema=False,\n)\ndef titan_security_logo() -> FileResponse:\n    logo_path = (\n        BACKEND_ROOT\n        / "app"\n        / "static"\n        / "branding"\n        / "titan-logo.png"\n    )\n    return FileResponse(\n        path=logo_path,\n        media_type="image/png",\n        filename="titan-logo.png",\n    )\n\n\n@router.get(\n    "/verify-email-link",\n    response_class=HTMLResponse,\n    include_in_schema=False,\n)\ndef verification_landing_page(\n    token: str = Query(min_length=32, max_length=512),\n) -> HTMLResponse:\n    return HTMLResponse(\n        content=verification_confirmation_page(token=token)\n    )\n\n\n@router.post(\n    "/verify-email-link",\n    response_class=HTMLResponse,\n    include_in_schema=False,\n)\ndef verification_landing_confirm(\n    token: str = Form(..., min_length=32, max_length=512),\n    db: Session = Depends(get_db),\n) -> HTMLResponse:\n    try:\n        EmailVerificationService(db).verify(token)\n        return HTMLResponse(\n            content=verification_success_page()\n        )\n    except InvalidEmailVerificationTokenError:\n        return HTMLResponse(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            content=verification_error_page(),\n        )\n'
FILES[PROJECT_ROOT / 'backend/tests/test_password_reset.py'] = 'import uuid\nfrom datetime import datetime, timedelta, timezone\n\nfrom fastapi.testclient import TestClient\nfrom sqlalchemy import select\n\nfrom app.core.database import SessionLocal\nfrom app.main import app\nfrom app.models.password_reset_token import PasswordResetToken\nfrom app.models.user import User\nfrom app.models.user_session import UserSession\nfrom app.security.passwords import verify_password\nfrom app.services.auth_service import AuthenticationService\nfrom app.services.password_reset_service import (\n    InvalidPasswordResetTokenError,\n    PasswordResetService,\n)\n\n\nclient = TestClient(app)\n\n\ndef _cleanup_email(email: str) -> None:\n    with SessionLocal() as db:\n        user = db.scalars(\n            select(User).where(User.email == email)\n        ).first()\n        if user is not None:\n            db.delete(user)\n            db.commit()\n\n\ndef _register(email: str, password: str) -> None:\n    response = client.post(\n        "/api/v1/auth/register",\n        json={"email": email, "password": password},\n    )\n    assert response.status_code == 201\n\n\ndef test_forgot_password_does_not_disclose_account_existence() -> None:\n    real_email = f"reset-real-{uuid.uuid4()}@example.com"\n    missing_email = f"reset-missing-{uuid.uuid4()}@example.com"\n    password = "password reset development password"\n\n    try:\n        _register(real_email, password)\n\n        real = client.post(\n            "/api/v1/auth/forgot-password",\n            json={"email": real_email},\n        )\n        missing = client.post(\n            "/api/v1/auth/forgot-password",\n            json={"email": missing_email},\n        )\n\n        assert real.status_code == 202\n        assert missing.status_code == 202\n        assert real.json() == missing.json()\n        assert real.json() == {\n            "status": "password_reset_pending"\n        }\n    finally:\n        _cleanup_email(real_email)\n\n\ndef test_password_reset_hashes_token_and_changes_password() -> None:\n    email = f"reset-change-{uuid.uuid4()}@example.com"\n    old_password = "old password reset development value"\n    new_password = "new password reset development value"\n\n    try:\n        _register(email, old_password)\n\n        with SessionLocal() as db:\n            reset = PasswordResetService(db).request_reset(email)\n            assert reset is not None\n            user, raw_token = reset\n\n            token = db.scalars(\n                select(PasswordResetToken).where(\n                    PasswordResetToken.user_id == user.id,\n                    PasswordResetToken.used_at.is_(None),\n                    PasswordResetToken.invalidated_at.is_(None),\n                )\n            ).one()\n\n            assert len(token.token_hash) == 64\n            assert token.token_hash != raw_token\n            old_changed_at = user.id\n\n        with SessionLocal() as db:\n            PasswordResetService(db).reset_password(\n                raw_token=raw_token,\n                new_password=new_password,\n            )\n\n        with SessionLocal() as db:\n            user = db.scalars(\n                select(User).where(User.email == email)\n            ).one()\n            credential = AuthenticationService(db).credentials.get_by_user_id(\n                user.id\n            )\n            assert credential is not None\n            assert verify_password(\n                new_password,\n                credential.password_hash,\n            )\n            assert not verify_password(\n                old_password,\n                credential.password_hash,\n            )\n            assert credential.password_changed_at is not None\n    finally:\n        _cleanup_email(email)\n\n\ndef test_password_reset_token_is_single_use() -> None:\n    email = f"reset-single-{uuid.uuid4()}@example.com"\n    password = "single use reset development password"\n\n    try:\n        _register(email, password)\n\n        with SessionLocal() as db:\n            reset = PasswordResetService(db).request_reset(email)\n            assert reset is not None\n            _, raw_token = reset\n\n        with SessionLocal() as db:\n            PasswordResetService(db).reset_password(\n                raw_token=raw_token,\n                new_password="first changed development password",\n            )\n\n        with SessionLocal() as db:\n            try:\n                PasswordResetService(db).reset_password(\n                    raw_token=raw_token,\n                    new_password="second changed development password",\n                )\n            except InvalidPasswordResetTokenError:\n                pass\n            else:\n                raise AssertionError("Used reset token was accepted twice")\n    finally:\n        _cleanup_email(email)\n\n\ndef test_expired_password_reset_token_is_rejected() -> None:\n    email = f"reset-expired-{uuid.uuid4()}@example.com"\n    password = "expired reset development password"\n\n    try:\n        _register(email, password)\n\n        with SessionLocal() as db:\n            reset = PasswordResetService(db).request_reset(email)\n            assert reset is not None\n            user, raw_token = reset\n            token = db.scalars(\n                select(PasswordResetToken).where(\n                    PasswordResetToken.user_id == user.id,\n                    PasswordResetToken.invalidated_at.is_(None),\n                )\n            ).one()\n            token.expires_at = (\n                datetime.now(timezone.utc) - timedelta(minutes=1)\n            )\n            db.commit()\n\n        with SessionLocal() as db:\n            try:\n                PasswordResetService(db).reset_password(\n                    raw_token=raw_token,\n                    new_password="expired changed development password",\n                )\n            except InvalidPasswordResetTokenError:\n                pass\n            else:\n                raise AssertionError("Expired reset token was accepted")\n    finally:\n        _cleanup_email(email)\n\n\ndef test_password_reset_revokes_existing_sessions() -> None:\n    email = f"reset-session-{uuid.uuid4()}@example.com"\n    password = "session reset development password"\n\n    try:\n        _register(email, password)\n\n        login = client.post(\n            "/api/v1/auth/login",\n            json={"email": email, "password": password},\n        )\n        assert login.status_code == 200\n        access_token = login.json()["access_token"]\n\n        with SessionLocal() as db:\n            reset = PasswordResetService(db).request_reset(email)\n            assert reset is not None\n            user, raw_token = reset\n\n        with SessionLocal() as db:\n            PasswordResetService(db).reset_password(\n                raw_token=raw_token,\n                new_password="replacement session development password",\n            )\n\n        old_me = client.get(\n            "/api/v1/auth/me",\n            headers={"Authorization": f"Bearer {access_token}"},\n        )\n        assert old_me.status_code == 401\n\n        with SessionLocal() as db:\n            sessions = db.scalars(\n                select(UserSession).where(\n                    UserSession.user_id == user.id\n                )\n            ).all()\n            assert sessions\n            assert all(\n                session.revoked_at is not None\n                for session in sessions\n            )\n    finally:\n        _cleanup_email(email)\n'
FILES[PROJECT_ROOT / 'backend/tests/test_security_pages.py'] = 'from app.presentation.security_pages import (\n    password_reset_error_page,\n    password_reset_form_page,\n    password_reset_success_page,\n    verification_confirmation_page,\n    verification_error_page,\n    verification_success_page,\n)\n\n\ndef test_verification_confirmation_uses_philotes_security_shell() -> None:\n    html = verification_confirmation_page(\n        token="development-token-123456789012345678901234567890"\n    )\n\n    assert "PHILOTES" in html\n    assert "A Community for Friendship" in html\n    assert "BROUGHT TO YOU BY" in html\n    assert "/api/v1/auth/security-assets/titan-logo.png" in html\n    assert ">TITAN</span>" in html\n    assert "Verify Email Address" in html\n    assert "--philotes-navy" in html\n    assert "--philotes-gold" in html\n\n\ndef test_verification_success_uses_philotes_security_shell() -> None:\n    html = verification_success_page()\n\n    assert "Email verified" in html\n    assert "successfully verified" in html\n    assert "return to Philotes" in html\n    assert "BROUGHT TO YOU BY" in html\n    assert "/api/v1/auth/security-assets/titan-logo.png" in html\n    assert ">TITAN</span>" in html\n\n\ndef test_verification_error_uses_philotes_security_shell() -> None:\n    html = verification_error_page()\n\n    assert "Verification link unavailable" in html\n    assert "invalid, expired, or has already been used" in html\n    assert "Request a new verification email" in html\n    assert "BROUGHT TO YOU BY" in html\n    assert "/api/v1/auth/security-assets/titan-logo.png" in html\n\n\n\ndef test_password_reset_pages_use_philotes_security_shell() -> None:\n    form = password_reset_form_page(\n        token="reset-development-token-123456789012345678901234"\n    )\n    success = password_reset_success_page()\n    error = password_reset_error_page()\n\n    for html in (form, success, error):\n        assert "PHILOTES" in html\n        assert "A Community for Friendship" in html\n        assert "BROUGHT TO YOU BY" in html\n        assert "/api/v1/auth/security-assets/titan-logo.png" in html\n        assert ">TITAN</span>" in html\n\n    assert "Change Password" in form\n    assert "Password changed" in success\n    assert "Reset link unavailable" in error\n'
FILES[PROJECT_ROOT / 'backend/tests/test_email_delivery.py'] = 'import uuid\n\nfrom fastapi.testclient import TestClient\nfrom sqlalchemy import select\n\nfrom app.core.config import settings\nfrom app.core.database import SessionLocal\nfrom app.main import app\nfrom app.models.user import User\nfrom app.providers.resend_email_provider import ResendEmailProvider\nfrom app.services.email_delivery_service import EmailDeliveryService\n\n\nclient = TestClient(app)\n\n\ndef _cleanup_email(email: str) -> None:\n    with SessionLocal() as db:\n        user = db.scalars(\n            select(User).where(User.email == email)\n        ).first()\n        if user is not None:\n            db.delete(user)\n            db.commit()\n\n\ndef test_resend_provider_builds_expected_message(monkeypatch) -> None:\n    captured: dict = {}\n\n    def fake_send(params):\n        captured.update(params)\n        return {"id": "development-email-id"}\n\n    monkeypatch.setattr(\n        "app.providers.resend_email_provider.resend.Emails.send",\n        fake_send,\n    )\n    monkeypatch.setattr(\n        settings,\n        "resend_api_key",\n        "re_development_test_key",\n    )\n\n    EmailDeliveryService(\n        provider=ResendEmailProvider()\n    ).send_verification_email(\n        to_email="delivery-test@example.com",\n        raw_token="development-verification-token-1234567890",\n    )\n\n    assert captured["from"] == settings.email_from_address\n    assert captured["to"] == ["delivery-test@example.com"]\n    assert captured["subject"] == "Verify your Philotes email"\n    assert "development-verification-token" in captured["html"]\n    assert "development-verification-token" in captured["text"]\n\n\ndef test_verification_link_get_does_not_verify_email() -> None:\n    email = f"email-link-{uuid.uuid4()}@example.com"\n    password = "verification delivery development password"\n\n    try:\n        registration = client.post(\n            "/api/v1/auth/register",\n            json={"email": email, "password": password},\n        )\n        assert registration.status_code == 201\n\n        with SessionLocal() as db:\n            user = db.scalars(\n                select(User).where(User.email == email)\n            ).one()\n            token = EmailDeliveryService.build_verification_url(\n                "placeholder-token-value-12345678901234567890"\n            )\n            assert user.email_verified is False\n\n        # The GET landing page must never consume a token. Link scanners\n        # may prefetch verification links.\n        response = client.get(\n            "/api/v1/auth/verify-email-link",\n            params={\n                "token": "placeholder-token-value-12345678901234567890"\n            },\n        )\n        assert response.status_code == 200\n\n        with SessionLocal() as db:\n            user = db.scalars(\n                select(User).where(User.email == email)\n            ).one()\n            assert user.email_verified is False\n    finally:\n        _cleanup_email(email)\n\n\n\ndef test_resend_provider_builds_password_reset_message(monkeypatch) -> None:\n    captured: dict = {}\n\n    def fake_send(params):\n        captured.update(params)\n        return {"id": "development-reset-email-id"}\n\n    monkeypatch.setattr(\n        "app.providers.resend_email_provider.resend.Emails.send",\n        fake_send,\n    )\n    monkeypatch.setattr(\n        settings,\n        "resend_api_key",\n        "re_development_test_key",\n    )\n\n    EmailDeliveryService(\n        provider=ResendEmailProvider()\n    ).send_password_reset_email(\n        to_email="reset-delivery-test@example.com",\n        raw_token="development-reset-token-12345678901234567890",\n    )\n\n    assert captured["from"] == settings.email_from_address\n    assert captured["to"] == ["reset-delivery-test@example.com"]\n    assert captured["subject"] == "Reset your Philotes password"\n    assert "development-reset-token" in captured["html"]\n    assert "development-reset-token" in captured["text"]\n'


