FILES[PROJECT_ROOT / 'backend/app/models/user_session.py'] = 'import uuid\nfrom datetime import datetime\n\nfrom sqlalchemy import DateTime, ForeignKey, String, Uuid, func\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom .base import Base\n\n\nclass UserSession(Base):\n    __tablename__ = "user_sessions"\n\n    id: Mapped[uuid.UUID] = mapped_column(\n        Uuid,\n        primary_key=True,\n        default=uuid.uuid4,\n    )\n    user_id: Mapped[uuid.UUID] = mapped_column(\n        Uuid,\n        ForeignKey("users.id", ondelete="CASCADE"),\n        nullable=False,\n        index=True,\n    )\n    device_name: Mapped[str | None] = mapped_column(\n        String(120),\n        nullable=True,\n    )\n    platform: Mapped[str | None] = mapped_column(\n        String(50),\n        nullable=True,\n    )\n    client_name: Mapped[str | None] = mapped_column(\n        String(100),\n        nullable=True,\n    )\n    refresh_token_hash: Mapped[str] = mapped_column(\n        String(64),\n        nullable=False,\n        unique=True,\n        index=True,\n    )\n    created_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        nullable=False,\n        server_default=func.now(),\n    )\n    last_used_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        nullable=False,\n        server_default=func.now(),\n    )\n    expires_at: Mapped[datetime] = mapped_column(\n        DateTime(timezone=True),\n        nullable=False,\n    )\n    revoked_at: Mapped[datetime | None] = mapped_column(\n        DateTime(timezone=True),\n        nullable=True,\n    )\n'
FILES[PROJECT_ROOT / 'backend/app/repositories/user_session_repository.py'] = 'import uuid\nfrom datetime import datetime\n\nfrom sqlalchemy import select, update\nfrom sqlalchemy.orm import Session\n\nfrom ..models.user_session import UserSession\n\n\nclass UserSessionRepository:\n    def __init__(self, db: Session) -> None:\n        self.db = db\n\n    def get_by_id(self, session_id: uuid.UUID) -> UserSession | None:\n        return self.db.get(UserSession, session_id)\n\n    def get_by_refresh_hash(self, refresh_token_hash: str) -> UserSession | None:\n        statement = select(UserSession).where(\n            UserSession.refresh_token_hash == refresh_token_hash\n        )\n        return self.db.scalars(statement).first()\n\n    def create(\n        self,\n        user_id: uuid.UUID,\n        refresh_token_hash: str,\n        expires_at: datetime,\n        *,\n        device_name: str | None = None,\n        platform: str | None = None,\n        client_name: str | None = None,\n    ) -> UserSession:\n        session = UserSession(\n            user_id=user_id,\n            device_name=device_name,\n            platform=platform,\n            client_name=client_name,\n            refresh_token_hash=refresh_token_hash,\n            expires_at=expires_at,\n        )\n        self.db.add(session)\n        self.db.flush()\n        return session\n\n\n    def revoke_all_for_user(\n        self,\n        user_id: uuid.UUID,\n        when: datetime,\n    ) -> None:\n        statement = (\n            update(UserSession)\n            .where(\n                UserSession.user_id == user_id,\n                UserSession.revoked_at.is_(None),\n            )\n            .values(revoked_at=when)\n        )\n        self.db.execute(statement)\n\n\n    def list_active_for_user(\n        self,\n        user_id: uuid.UUID,\n        now: datetime,\n    ) -> list[UserSession]:\n        statement = (\n            select(UserSession)\n            .where(\n                UserSession.user_id == user_id,\n                UserSession.revoked_at.is_(None),\n                UserSession.expires_at > now,\n            )\n            .order_by(UserSession.created_at.desc())\n        )\n        return list(self.db.scalars(statement).all())\n\n    def revoke_by_id_for_user(\n        self,\n        *,\n        user_id: uuid.UUID,\n        session_id: uuid.UUID,\n        when: datetime,\n    ) -> bool:\n        session = self.get_by_id(session_id)\n        if (\n            session is None\n            or session.user_id != user_id\n            or session.revoked_at is not None\n        ):\n            return False\n\n        session.revoked_at = when\n        return True\n\n    def revoke_others_for_user(\n        self,\n        *,\n        user_id: uuid.UUID,\n        current_session_id: uuid.UUID,\n        when: datetime,\n    ) -> None:\n        statement = (\n            update(UserSession)\n            .where(\n                UserSession.user_id == user_id,\n                UserSession.id != current_session_id,\n                UserSession.revoked_at.is_(None),\n            )\n            .values(revoked_at=when)\n        )\n        self.db.execute(statement)\n\n    def touch(\n        self,\n        session_id: uuid.UUID,\n        when: datetime,\n    ) -> None:\n        session = self.get_by_id(session_id)\n        if session is not None and session.revoked_at is None:\n            session.last_used_at = when\n'
FILES[PROJECT_ROOT / 'backend/app/schemas/session.py'] = 'import uuid\nfrom datetime import datetime\n\nfrom pydantic import BaseModel\n\n\nclass SessionResponse(BaseModel):\n    id: uuid.UUID\n    device_name: str | None\n    platform: str | None\n    client_name: str | None\n    signed_in_at: datetime\n    last_active_at: datetime\n    expires_at: datetime\n    is_current: bool\n\n\nclass SessionListResponse(BaseModel):\n    sessions: list[SessionResponse]\n'
FILES[PROJECT_ROOT / 'backend/app/schemas/__init__.py'] = 'from .auth import (\n    ChangePasswordRequest,\n    ForgotPasswordRequest,\n    LoginRequest,\n    LogoutRequest,\n    PasswordResetStatusResponse,\n    RefreshRequest,\n    RegistrationRequest,\n    TokenResponse,\n    VerificationStatusResponse,\n    VerifyEmailRequest,\n)\nfrom .user import UserCreate, UserResponse\n\n\n__all__ = [\n    "SessionListResponse",\n    "SessionResponse",\n    "ChangePasswordRequest",\n    "ForgotPasswordRequest",\n    "LoginRequest",\n    "LogoutRequest",\n    "PasswordResetStatusResponse",\n    "RefreshRequest",\n    "RegistrationRequest",\n    "TokenResponse",\n    "VerificationStatusResponse",\n    "VerifyEmailRequest",\n    "UserCreate",\n    "UserResponse",\n]\n\n\nfrom .session import SessionListResponse, SessionResponse\n'
FILES[PROJECT_ROOT / 'backend/app/security/authentication.py'] = 'import uuid\nfrom dataclasses import dataclass\n\nfrom fastapi import Depends, HTTPException, status\nfrom fastapi.security import HTTPAuthorizationCredentials, HTTPBearer\nfrom sqlalchemy.orm import Session\n\nfrom ..core.database import get_db\nfrom ..models.user import User\nfrom ..services.auth_service import AuthenticationService, InvalidCredentialsError\nfrom .tokens import AccessTokenError, decode_access_token\n\n\nbearer_scheme = HTTPBearer(auto_error=False)\n\n\n@dataclass(frozen=True)\nclass AuthenticatedSession:\n    user: User\n    session_id: uuid.UUID\n\n\ndef get_authenticated_session(\n    credentials: HTTPAuthorizationCredentials | None = Depends(bearer_scheme),\n    db: Session = Depends(get_db),\n) -> AuthenticatedSession:\n    unauthorized = HTTPException(\n        status_code=status.HTTP_401_UNAUTHORIZED,\n        detail="Authentication required.",\n        headers={"WWW-Authenticate": "Bearer"},\n    )\n\n    if credentials is None or credentials.scheme.lower() != "bearer":\n        raise unauthorized\n\n    try:\n        user_id, session_id = decode_access_token(credentials.credentials)\n        user = AuthenticationService(db).get_session_user(\n            user_id,\n            session_id,\n        )\n        return AuthenticatedSession(\n            user=user,\n            session_id=session_id,\n        )\n    except (AccessTokenError, InvalidCredentialsError) as exc:\n        raise unauthorized from exc\n\n\ndef get_current_user(\n    authenticated: AuthenticatedSession = Depends(get_authenticated_session),\n) -> User:\n    return authenticated.user\n\n\ndef get_verified_user(\n    current_user: User = Depends(get_current_user),\n) -> User:\n    if not current_user.email_verified:\n        raise HTTPException(\n            status_code=status.HTTP_403_FORBIDDEN,\n            detail="Email verification required.",\n        )\n\n    return current_user\n'
FILES[PROJECT_ROOT / 'backend/app/services/session_service.py'] = 'import uuid\nfrom datetime import datetime, timezone\n\nfrom sqlalchemy.orm import Session\n\nfrom ..models.user_session import UserSession\nfrom ..repositories.user_session_repository import UserSessionRepository\n\n\nclass SessionNotFoundError(Exception):\n    pass\n\n\nclass CurrentSessionRevocationError(Exception):\n    pass\n\n\nclass SessionService:\n    def __init__(self, db: Session) -> None:\n        self.db = db\n        self.sessions = UserSessionRepository(db)\n\n    def list_active(\n        self,\n        *,\n        user_id: uuid.UUID,\n        current_session_id: uuid.UUID,\n    ) -> list[tuple[UserSession, bool]]:\n        now = datetime.now(timezone.utc)\n        records = self.sessions.list_active_for_user(user_id, now)\n        self.sessions.touch(current_session_id, now)\n        self.db.commit()\n\n        return [\n            (record, record.id == current_session_id)\n            for record in records\n        ]\n\n    def revoke_session(\n        self,\n        *,\n        user_id: uuid.UUID,\n        current_session_id: uuid.UUID,\n        session_id: uuid.UUID,\n    ) -> None:\n        if session_id == current_session_id:\n            raise CurrentSessionRevocationError\n\n        revoked = self.sessions.revoke_by_id_for_user(\n            user_id=user_id,\n            session_id=session_id,\n            when=datetime.now(timezone.utc),\n        )\n        if not revoked:\n            raise SessionNotFoundError\n\n        self.db.commit()\n\n    def revoke_others(\n        self,\n        *,\n        user_id: uuid.UUID,\n        current_session_id: uuid.UUID,\n    ) -> None:\n        self.sessions.revoke_others_for_user(\n            user_id=user_id,\n            current_session_id=current_session_id,\n            when=datetime.now(timezone.utc),\n        )\n        self.db.commit()\n\n    def revoke_everywhere(\n        self,\n        *,\n        user_id: uuid.UUID,\n    ) -> None:\n        self.sessions.revoke_all_for_user(\n            user_id,\n            datetime.now(timezone.utc),\n        )\n        self.db.commit()\n'
FILES[PROJECT_ROOT / 'backend/app/services/__init__.py'] = 'from .auth_service import (\n    AuthenticationService,\n    InactiveUserError,\n    InvalidCredentialsError,\n    InvalidRefreshTokenError,\n)\nfrom .email_delivery_service import EmailDeliveryService\nfrom .email_verification_service import (\n    EmailVerificationService,\n    InvalidEmailVerificationTokenError,\n)\nfrom .password_reset_service import (\n    InvalidPasswordResetTokenError,\n    PasswordResetService,\n)\nfrom .user_service import UserAlreadyExistsError, UserNotFoundError, UserService\n\n\n__all__ = [\n    "CurrentSessionRevocationError",\n    "SessionNotFoundError",\n    "SessionService",\n    "AuthenticationService",\n    "EmailDeliveryService",\n    "EmailVerificationService",\n    "InactiveUserError",\n    "InvalidCredentialsError",\n    "InvalidEmailVerificationTokenError",\n    "InvalidRefreshTokenError",\n    "InvalidPasswordResetTokenError",\n    "PasswordResetService",\n    "UserAlreadyExistsError",\n    "UserNotFoundError",\n    "UserService",\n]\n\n\nfrom .session_service import (\n    CurrentSessionRevocationError,\n    SessionNotFoundError,\n    SessionService,\n)\n'
FILES[PROJECT_ROOT / 'backend/app/services/auth_service.py'] = 'import uuid\nfrom datetime import datetime, timedelta, timezone\n\nfrom sqlalchemy.exc import IntegrityError\nfrom sqlalchemy.orm import Session\n\nfrom ..core.config import settings\nfrom ..models.user import User\nfrom ..repositories.user_credential_repository import UserCredentialRepository\nfrom ..repositories.user_repository import UserRepository\nfrom ..repositories.user_session_repository import UserSessionRepository\nfrom ..security.passwords import hash_password, verify_password\nfrom ..security.tokens import (\n    create_access_token,\n    create_refresh_token,\n    hash_refresh_token,\n)\nfrom .email_verification_service import EmailVerificationService\nfrom .user_service import UserAlreadyExistsError, UserService\n\n\nclass InvalidCredentialsError(Exception):\n    pass\n\n\nclass InactiveUserError(Exception):\n    pass\n\n\nclass InvalidRefreshTokenError(Exception):\n    pass\n\n\nclass InvalidCurrentPasswordError(Exception):\n    pass\n\n\nclass PasswordReuseError(Exception):\n    pass\n\n\nclass AuthenticationService:\n    def __init__(self, db: Session) -> None:\n        self.db = db\n        self.users = UserRepository(db)\n        self.credentials = UserCredentialRepository(db)\n        self.sessions = UserSessionRepository(db)\n        self.email_verifications = EmailVerificationService(db)\n\n    def register(\n        self,\n        email: str,\n        password: str,\n    ) -> tuple[User, str]:\n        normalized_email = UserService.normalize_email(email)\n\n        if self.users.get_by_email(normalized_email) is not None:\n            raise UserAlreadyExistsError\n\n        try:\n            user = User(email=normalized_email)\n            self.db.add(user)\n            self.db.flush()\n\n            self.credentials.create(\n                user_id=user.id,\n                password_hash=hash_password(password),\n            )\n            verification_token = self.email_verifications.issue_token(\n                user.id,\n                commit=False,\n            )\n\n            self.db.commit()\n            self.db.refresh(user)\n            return user, verification_token\n        except IntegrityError as exc:\n            self.db.rollback()\n            raise UserAlreadyExistsError from exc\n        except Exception:\n            self.db.rollback()\n            raise\n\n    def login(\n        self,\n        email: str,\n        password: str,\n        *,\n        device_name: str | None = None,\n        platform: str | None = None,\n        client_name: str | None = None,\n    ) -> tuple[User, str, str, int]:\n        normalized_email = UserService.normalize_email(email)\n        user = self.users.get_by_email(normalized_email)\n\n        if user is None:\n            raise InvalidCredentialsError\n\n        credential = self.credentials.get_by_user_id(user.id)\n        if credential is None or not verify_password(\n            password,\n            credential.password_hash,\n        ):\n            raise InvalidCredentialsError\n\n        if not user.is_active:\n            raise InactiveUserError\n\n        refresh_token = create_refresh_token()\n        expires_at = datetime.now(timezone.utc) + timedelta(\n            days=settings.session_expire_days,\n        )\n\n        session = self.sessions.create(\n            user_id=user.id,\n            refresh_token_hash=hash_refresh_token(refresh_token),\n            expires_at=expires_at,\n            device_name=device_name,\n            platform=platform,\n            client_name=client_name,\n        )\n        self.db.commit()\n\n        access_token, expires_in = create_access_token(\n            user.id,\n            session.id,\n        )\n        return user, access_token, refresh_token, expires_in\n\n    def refresh(self, refresh_token: str) -> tuple[str, str, int]:\n        now = datetime.now(timezone.utc)\n        session = self.sessions.get_by_refresh_hash(\n            hash_refresh_token(refresh_token)\n        )\n\n        if (\n            session is None\n            or session.revoked_at is not None\n            or session.expires_at <= now\n        ):\n            raise InvalidRefreshTokenError\n\n        user = self.users.get_by_id(session.user_id)\n        if user is None or not user.is_active:\n            raise InvalidRefreshTokenError\n\n        new_refresh_token = create_refresh_token()\n        session.refresh_token_hash = hash_refresh_token(new_refresh_token)\n        session.last_used_at = now\n        self.db.commit()\n\n        access_token, expires_in = create_access_token(\n            user.id,\n            session.id,\n        )\n        return access_token, new_refresh_token, expires_in\n\n    def logout(self, refresh_token: str) -> None:\n        session = self.sessions.get_by_refresh_hash(\n            hash_refresh_token(refresh_token)\n        )\n\n        if session is None:\n            return\n\n        if session.revoked_at is None:\n            session.revoked_at = datetime.now(timezone.utc)\n            self.db.commit()\n\n    def change_password(\n        self,\n        *,\n        user_id: uuid.UUID,\n        current_password: str,\n        new_password: str,\n        device_name: str | None = None,\n        platform: str | None = None,\n        client_name: str | None = None,\n    ) -> tuple[str, str, int]:\n        credential = self.credentials.get_by_user_id(user_id)\n\n        if credential is None or not verify_password(\n            current_password,\n            credential.password_hash,\n        ):\n            raise InvalidCurrentPasswordError\n\n        if verify_password(\n            new_password,\n            credential.password_hash,\n        ):\n            raise PasswordReuseError\n\n        now = datetime.now(timezone.utc)\n\n        updated = self.credentials.update_password(\n            user_id=user_id,\n            password_hash=hash_password(new_password),\n            changed_at=now,\n        )\n        if updated is None:\n            raise InvalidCurrentPasswordError\n\n        # A password change is a security boundary. Revoke every\n        # pre-change session, including the session that submitted this\n        # request, then create a replacement session for this device.\n        self.sessions.revoke_all_for_user(user_id, now)\n\n        new_refresh_token = create_refresh_token()\n        replacement_session = self.sessions.create(\n            user_id=user_id,\n            refresh_token_hash=hash_refresh_token(new_refresh_token),\n            expires_at=now + timedelta(\n                days=settings.session_expire_days,\n            ),\n            device_name=device_name,\n            platform=platform,\n            client_name=client_name,\n        )\n\n        self.db.commit()\n\n        access_token, expires_in = create_access_token(\n            user_id,\n            replacement_session.id,\n        )\n        return access_token, new_refresh_token, expires_in\n\n    def get_session_user(\n        self,\n        user_id: uuid.UUID,\n        session_id: uuid.UUID,\n    ) -> User:\n        now = datetime.now(timezone.utc)\n        session = self.sessions.get_by_id(session_id)\n\n        if (\n            session is None\n            or session.user_id != user_id\n            or session.revoked_at is not None\n            or session.expires_at <= now\n        ):\n            raise InvalidCredentialsError\n\n        user = self.users.get_by_id(user_id)\n        if user is None or not user.is_active:\n            raise InvalidCredentialsError\n\n        return user\n'
FILES[PROJECT_ROOT / 'backend/app/api/routes/auth.py'] = 'from fastapi import (\n    APIRouter,\n    BackgroundTasks,\n    Depends,\n    Form,\n    HTTPException,\n    Query,\n    Request,\n    Response,\n    status,\n)\nfrom fastapi.responses import FileResponse, HTMLResponse\nfrom sqlalchemy.exc import SQLAlchemyError\nfrom sqlalchemy.orm import Session\n\nfrom ...core.config import BACKEND_ROOT, settings\nfrom ...core.database import get_db\nfrom ...schemas.auth import (\n    ChangePasswordRequest,\n    ForgotPasswordRequest,\n    LoginRequest,\n    LogoutRequest,\n    PasswordResetStatusResponse,\n    RefreshRequest,\n    RegistrationRequest,\n    TokenResponse,\n    VerificationStatusResponse,\n    VerifyEmailRequest,\n)\nfrom ...schemas.user import UserResponse\nfrom ...security.authentication import get_current_user\nfrom ...services.email_delivery_service import EmailDeliveryService\nfrom ...services.email_verification_service import (\n    EmailVerificationService,\n    InvalidEmailVerificationTokenError,\n)\nfrom ...services.auth_service import (\n    AuthenticationService,\n    InvalidCurrentPasswordError,\n    InactiveUserError,\n    InvalidCredentialsError,\n    InvalidRefreshTokenError,\n    PasswordReuseError,\n)\nfrom ...services.password_reset_service import (\n    InvalidPasswordResetTokenError,\n    PasswordResetService,\n)\nfrom ...services.user_service import UserAlreadyExistsError\nfrom ...models.user import User\nfrom ...presentation.security_pages import (\n    password_reset_error_page,\n    password_reset_form_page,\n    password_reset_success_page,\n    verification_confirmation_page,\n    verification_error_page,\n    verification_success_page,\n)\n\n\nrouter = APIRouter(\n    prefix="/auth",\n    tags=["Authentication"],\n)\n\n\n@router.post(\n    "/register",\n    response_model=UserResponse,\n    status_code=status.HTTP_201_CREATED,\n)\ndef register(\n    payload: RegistrationRequest,\n    background_tasks: BackgroundTasks,\n    db: Session = Depends(get_db),\n) -> UserResponse:\n    service = AuthenticationService(db)\n\n    try:\n        user, verification_token = service.register(\n            email=str(payload.email),\n            password=payload.password,\n        )\n\n        if settings.email_delivery_enabled:\n            background_tasks.add_task(\n                EmailDeliveryService().send_verification_email,\n                to_email=user.email,\n                raw_token=verification_token,\n            )\n\n        return user\n    except UserAlreadyExistsError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_409_CONFLICT,\n            detail="An account with that email already exists.",\n        ) from exc\n    except SQLAlchemyError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\n            detail="Database unavailable",\n        ) from exc\n\n\n@router.post(\n    "/login",\n    response_model=TokenResponse,\n)\ndef login(\n    payload: LoginRequest,\n    request: Request,\n    db: Session = Depends(get_db),\n) -> TokenResponse:\n    service = AuthenticationService(db)\n\n    try:\n        _, access_token, refresh_token, expires_in = service.login(\n            email=str(payload.email),\n            password=payload.password,\n            device_name=request.headers.get("X-Philotes-Device-Name"),\n            platform=request.headers.get("X-Philotes-Platform"),\n            client_name=request.headers.get("X-Philotes-Client"),\n        )\n        return TokenResponse(\n            access_token=access_token,\n            refresh_token=refresh_token,\n            expires_in=expires_in,\n        )\n    except InvalidCredentialsError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_401_UNAUTHORIZED,\n            detail="Invalid email or password.",\n        ) from exc\n    except InactiveUserError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_403_FORBIDDEN,\n            detail="Account is inactive.",\n        ) from exc\n    except SQLAlchemyError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\n            detail="Database unavailable",\n        ) from exc\n\n\n@router.post(\n    "/refresh",\n    response_model=TokenResponse,\n)\ndef refresh(\n    payload: RefreshRequest,\n    db: Session = Depends(get_db),\n) -> TokenResponse:\n    try:\n        access_token, refresh_token, expires_in = AuthenticationService(\n            db\n        ).refresh(payload.refresh_token)\n        return TokenResponse(\n            access_token=access_token,\n            refresh_token=refresh_token,\n            expires_in=expires_in,\n        )\n    except InvalidRefreshTokenError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_401_UNAUTHORIZED,\n            detail="Invalid or expired refresh token.",\n        ) from exc\n\n\n@router.post(\n    "/logout",\n    status_code=status.HTTP_204_NO_CONTENT,\n)\ndef logout(\n    payload: LogoutRequest,\n    db: Session = Depends(get_db),\n) -> Response:\n    AuthenticationService(db).logout(payload.refresh_token)\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n\n\n@router.get(\n    "/me",\n    response_model=UserResponse,\n)\ndef me(\n    current_user: User = Depends(get_current_user),\n) -> UserResponse:\n    return current_user\n\n\n@router.post(\n    "/verify-email",\n    response_model=VerificationStatusResponse,\n)\ndef verify_email(\n    payload: VerifyEmailRequest,\n    db: Session = Depends(get_db),\n) -> VerificationStatusResponse:\n    try:\n        EmailVerificationService(db).verify(payload.token)\n        return VerificationStatusResponse(status="verified")\n    except InvalidEmailVerificationTokenError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            detail="Invalid or expired verification token.",\n        ) from exc\n\n\n@router.post(\n    "/resend-verification",\n    response_model=VerificationStatusResponse,\n    status_code=status.HTTP_202_ACCEPTED,\n)\ndef resend_verification(\n    background_tasks: BackgroundTasks,\n    current_user: User = Depends(get_current_user),\n    db: Session = Depends(get_db),\n) -> VerificationStatusResponse:\n    if current_user.email_verified:\n        return VerificationStatusResponse(status="already_verified")\n\n    verification_token = EmailVerificationService(db).issue_token(\n        current_user.id\n    )\n\n    if settings.email_delivery_enabled:\n        background_tasks.add_task(\n            EmailDeliveryService().send_verification_email,\n            to_email=current_user.email,\n            raw_token=verification_token,\n        )\n\n    return VerificationStatusResponse(status="verification_pending")\n\n\n@router.post(\n    "/change-password",\n    response_model=TokenResponse,\n)\ndef change_password(\n    payload: ChangePasswordRequest,\n    request: Request,\n    current_user: User = Depends(get_current_user),\n    db: Session = Depends(get_db),\n) -> TokenResponse:\n    if payload.new_password != payload.confirm_password:\n        raise HTTPException(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            detail="The new password entries do not match.",\n        )\n\n    try:\n        access_token, refresh_token, expires_in = AuthenticationService(\n            db\n        ).change_password(\n            user_id=current_user.id,\n            current_password=payload.current_password,\n            new_password=payload.new_password,\n            device_name=request.headers.get("X-Philotes-Device-Name"),\n            platform=request.headers.get("X-Philotes-Platform"),\n            client_name=request.headers.get("X-Philotes-Client"),\n        )\n        return TokenResponse(\n            access_token=access_token,\n            refresh_token=refresh_token,\n            expires_in=expires_in,\n        )\n    except InvalidCurrentPasswordError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            detail="Current password is incorrect.",\n        ) from exc\n    except PasswordReuseError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            detail="New password must be different from the current password.",\n        ) from exc\n\n\n@router.post(\n    "/forgot-password",\n    response_model=PasswordResetStatusResponse,\n    status_code=status.HTTP_202_ACCEPTED,\n)\ndef forgot_password(\n    payload: ForgotPasswordRequest,\n    background_tasks: BackgroundTasks,\n    db: Session = Depends(get_db),\n) -> PasswordResetStatusResponse:\n    reset = PasswordResetService(db).request_reset(str(payload.email))\n\n    if reset is not None and settings.email_delivery_enabled:\n        user, raw_token = reset\n        background_tasks.add_task(\n            EmailDeliveryService().send_password_reset_email,\n            to_email=user.email,\n            raw_token=raw_token,\n        )\n\n    # Deliberately identical whether or not the account exists.\n    return PasswordResetStatusResponse(status="password_reset_pending")\n\n\n@router.get(\n    "/reset-password-link",\n    response_class=HTMLResponse,\n    include_in_schema=False,\n)\ndef password_reset_landing_page(\n    token: str = Query(min_length=32, max_length=512),\n) -> HTMLResponse:\n    return HTMLResponse(\n        content=password_reset_form_page(token=token)\n    )\n\n\n@router.post(\n    "/reset-password-link",\n    response_class=HTMLResponse,\n    include_in_schema=False,\n)\ndef password_reset_landing_confirm(\n    token: str = Form(..., min_length=32, max_length=512),\n    new_password: str = Form(..., min_length=15, max_length=128),\n    confirm_password: str = Form(..., min_length=15, max_length=128),\n    db: Session = Depends(get_db),\n) -> HTMLResponse:\n    if new_password != confirm_password:\n        return HTMLResponse(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            content=password_reset_form_page(\n                token=token,\n                error_message="The password entries do not match.",\n            ),\n        )\n\n    try:\n        PasswordResetService(db).reset_password(\n            raw_token=token,\n            new_password=new_password,\n        )\n        return HTMLResponse(\n            content=password_reset_success_page()\n        )\n    except InvalidPasswordResetTokenError:\n        return HTMLResponse(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            content=password_reset_error_page(),\n        )\n\n\n@router.get(\n    "/security-assets/titan-logo.png",\n    response_class=FileResponse,\n    include_in_schema=False,\n)\ndef titan_security_logo() -> FileResponse:\n    logo_path = (\n        BACKEND_ROOT\n        / "app"\n        / "static"\n        / "branding"\n        / "titan-logo.png"\n    )\n    return FileResponse(\n        path=logo_path,\n        media_type="image/png",\n        filename="titan-logo.png",\n    )\n\n\n@router.get(\n    "/verify-email-link",\n    response_class=HTMLResponse,\n    include_in_schema=False,\n)\ndef verification_landing_page(\n    token: str = Query(min_length=32, max_length=512),\n) -> HTMLResponse:\n    return HTMLResponse(\n        content=verification_confirmation_page(token=token)\n    )\n\n\n@router.post(\n    "/verify-email-link",\n    response_class=HTMLResponse,\n    include_in_schema=False,\n)\ndef verification_landing_confirm(\n    token: str = Form(..., min_length=32, max_length=512),\n    db: Session = Depends(get_db),\n) -> HTMLResponse:\n    try:\n        EmailVerificationService(db).verify(token)\n        return HTMLResponse(\n            content=verification_success_page()\n        )\n    except InvalidEmailVerificationTokenError:\n        return HTMLResponse(\n            status_code=status.HTTP_400_BAD_REQUEST,\n            content=verification_error_page(),\n        )\n'
FILES[PROJECT_ROOT / 'backend/app/api/routes/sessions.py'] = 'import uuid\n\nfrom fastapi import APIRouter, Depends, HTTPException, Response, status\nfrom sqlalchemy.orm import Session\n\nfrom ...core.database import get_db\nfrom ...schemas.session import SessionListResponse, SessionResponse\nfrom ...security.authentication import (\n    AuthenticatedSession,\n    get_authenticated_session,\n)\nfrom ...services.session_service import (\n    CurrentSessionRevocationError,\n    SessionNotFoundError,\n    SessionService,\n)\n\n\nrouter = APIRouter(\n    prefix="/sessions",\n    tags=["Sessions"],\n)\n\n\n@router.get(\n    "",\n    response_model=SessionListResponse,\n)\ndef list_sessions(\n    authenticated: AuthenticatedSession = Depends(\n        get_authenticated_session\n    ),\n    db: Session = Depends(get_db),\n) -> SessionListResponse:\n    records = SessionService(db).list_active(\n        user_id=authenticated.user.id,\n        current_session_id=authenticated.session_id,\n    )\n\n    return SessionListResponse(\n        sessions=[\n            SessionResponse(\n                id=session.id,\n                device_name=session.device_name,\n                platform=session.platform,\n                client_name=session.client_name,\n                signed_in_at=session.created_at,\n                last_active_at=session.last_used_at,\n                expires_at=session.expires_at,\n                is_current=is_current,\n            )\n            for session, is_current in records\n        ]\n    )\n\n\n@router.delete(\n    "/{session_id}",\n    status_code=status.HTTP_204_NO_CONTENT,\n)\ndef revoke_session(\n    session_id: uuid.UUID,\n    authenticated: AuthenticatedSession = Depends(\n        get_authenticated_session\n    ),\n    db: Session = Depends(get_db),\n) -> Response:\n    try:\n        SessionService(db).revoke_session(\n            user_id=authenticated.user.id,\n            current_session_id=authenticated.session_id,\n            session_id=session_id,\n        )\n        return Response(status_code=status.HTTP_204_NO_CONTENT)\n    except CurrentSessionRevocationError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_409_CONFLICT,\n            detail=(\n                "Use the normal sign-out action to end the "\n                "current session."\n            ),\n        ) from exc\n    except SessionNotFoundError as exc:\n        raise HTTPException(\n            status_code=status.HTTP_404_NOT_FOUND,\n            detail="Session not found.",\n        ) from exc\n\n\n@router.post(\n    "/sign-out-others",\n    status_code=status.HTTP_204_NO_CONTENT,\n)\ndef sign_out_others(\n    authenticated: AuthenticatedSession = Depends(\n        get_authenticated_session\n    ),\n    db: Session = Depends(get_db),\n) -> Response:\n    SessionService(db).revoke_others(\n        user_id=authenticated.user.id,\n        current_session_id=authenticated.session_id,\n    )\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n\n\n@router.post(\n    "/sign-out-everywhere",\n    status_code=status.HTTP_204_NO_CONTENT,\n)\ndef sign_out_everywhere(\n    authenticated: AuthenticatedSession = Depends(\n        get_authenticated_session\n    ),\n    db: Session = Depends(get_db),\n) -> Response:\n    SessionService(db).revoke_everywhere(\n        user_id=authenticated.user.id,\n    )\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\n'
